import sys, time, re

def send(line):
    print(line, flush=True)

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == 'uci':
            send('id name ResignBot')
            send('id author OpenAI')
            send('uciok')
        elif line == 'isready':
            send('readyok')
        elif line.startswith('setoption'):
            continue
        elif line.startswith('ucinewgame'):
            continue
        elif line.startswith('position'):
            continue
        elif line.startswith('go'):
            # Provide negative evaluation and null bestmove
            send('info depth 1 score cp -1000')
            send('bestmove 0000')
        elif line == 'quit':
            break
        else:
            # ignore other commands
            pass

if __name__ == '__main__':
    main()
